import Printer
import UIKit
import WebKit

class ViewController: UIViewController {
    private let bluetoothPrinterManager = BluetoothPrinterManager()
    private let dummyPrinter = DummyPrinter()

    @IBOutlet var webView: WKWebView!

    override func viewDidLoad() {
        super.viewDidLoad()

        bluetoothPrinterManager.errorReport = { error in
            print("printer error:", error)
        }

        // Show the generated bytes in the web view so the demo works without hardware.
        dummyPrinter.logsToConsole = false
        dummyPrinter.onWrite = { [weak self] data in
            let html = "<pre style='font-size:14px;word-break:break-all;white-space:pre-wrap'>"
                + "\(data.count) bytes\n\n" + data.map { String(format: "%02X ", $0) }.joined() + "</pre>"
            DispatchQueue.main.async { self?.webView.loadHTMLString(html, baseURL: nil) }
        }
    }

    @IBAction func touchPrint(sender: UIButton) {
        guard let image = UIImage(named: "demo"), let cgImage = image.cgImage else {
            return
        }

        let receipt = Receipt(.🖨️58(.utf8))
            <<~ .style(.initialize)
            <<~ .layout(.justification(.center))
            <<~ .style(.characterSize(width: 2, height: 2))
            <<< "Printer"
            <<~ .style(.characterSize(width: 1, height: 1))
            <<< Dividing.default()
            <<~ .layout(.justification(.left))
            <<< KVItem("Coffee", "3.50")
            <<< KVItem("Bagel", "2.00")
            <<~ .style(.emphasis(enable: true))
            <<< KVItem("Total", "5.50")
            <<~ .style(.emphasis(enable: false))
            <<< Dividing.default()
            <<~ .layout(.justification(.center))
            <<< ImageItem(cgImage, binarization: .dither)
            <<< QRCode(content: "https://github.com/KevinGong2013/Printer", moduleSize: 6)
            <<< Barcode("PRINTER-001", height: 60)
            <<~ .page(.printAndFeed(lines: 3))
            <<~ .page(.feedAndCut(partial: true, feed: 0))

        if bluetoothPrinterManager.canPrint {
            bluetoothPrinterManager.write(receipt) { error in
                print("print finished, error:", error.map { "\($0)" } ?? "none")
            }
        }

        dummyPrinter.write(receipt)
    }

    override func prepare(for segue: UIStoryboardSegue, sender: Any?) {
        if let vc = segue.destination as? BluetoothPrinterSelectTableViewController {
            vc.sectionTitle = "Choose Bluetooth Printer"
            vc.printerManager = bluetoothPrinterManager
        }
    }
}
